/* fetch-subscribe.js —— 订阅组件库数据获取（前端模块，浏览器兼容）
 *
 * edit-mode.js 直接 import 并调用，不走 HTTP。
 * demo 实现：fetchSubscribedLibraries() 直接返回写死的订阅数据（与 scripts 版本同源）。
 * 正式环境：替换函数体为真实获取（如 fetch Pixso API），**接口与输出结构不变**。
 *
 * 接口：
 *   fetchSubscribedLibraries() → Promise<SubscribeSnapshot>
 *   getLibraryById(id) → Promise<LibraryFull | null>
 *
 * 输出结构契约见文件内注释。
 */

/* 便捷单库接口 */
export async function getLibraryById(id) {
  const snap = await fetchSubscribedLibraries()
  return snap.libraries.find(l => l.id === id) || null
}

